package com.gmail.manhle240406.project.community;
import android.app.Application;import androidx.lifecycle.*;import com.gmail.manhle240406.project.AniloveApplication;import com.gmail.manhle240406.project.adoption.AdoptionApi;import com.gmail.manhle240406.project.foundation.*;import java.util.*;

/** Selected-adoption chat state rendered by the shared main-shell conversation surface. */
public final class AdoptionChatModel extends AndroidViewModel {
 public final MutableLiveData<Long> changes=new MutableLiveData<>(0L);public final List<Map<String,Object>> messages=new ArrayList<>();public String body="",error="",adoptionId,next;public boolean busy,sending,loaded,readOnly,lost;private long event,generation;private String pendingOperation,pendingBody;private final SavedStateHandle state;private final SessionGateway sessions;public final SessionEpoch.Ticket ticket;private final Runnable invalidation=()->{generation++;lost=true;messages.clear();body="";changed();};
 public AdoptionChatModel(Application app,SavedStateHandle saved){super(app);state=saved;sessions=((AniloveApplication)app).foundation().sessions;ticket=sessions.capture();if(!Objects.equals(saved.get("flow_chat_owner"),ticket.uid))clearPending();else{pendingOperation=saved.get("flow_chat_operation");pendingBody=saved.get("flow_chat_body");}sessions.onInvalidated(invalidation);}
 private void changed(){changes.setValue(++event);}private boolean current(long g){return !lost&&ticket.uid!=null&&sessions.current(ticket)&&generation==g;}
 public boolean pending(){return pendingOperation!=null;}
 public void open(String id){if(adoptionId!=null&&!adoptionId.equals(id)){messages.clear();next=null;loaded=false;}adoptionId=id;load(false);}
 @SuppressWarnings("unchecked") public void load(boolean older){if(busy||adoptionId==null||older&&next==null)return;busy=true;error="";long g=generation;Map<String,Object> input=new HashMap<>();input.put("kind","messages");input.put("adoptionId",adoptionId);input.put("before",older?next:null);AdoptionApi.call("flowRead",input).addOnCompleteListener(t->{if(!current(g))return;busy=false;if(!t.isSuccessful()){error="load";changed();return;}Map<String,Object> data=t.getResult();Object raw=data.get("rows");List<Map<String,Object>> page=raw instanceof List?(List<Map<String,Object>>)raw:Collections.emptyList();if(!older)messages.clear();for(Map<String,Object> row:page)if(messages.stream().noneMatch(x->Objects.equals(x.get("messageId"),row.get("messageId"))))messages.add(new HashMap<>(row));while(messages.size()>100)messages.remove(0);next=data.get("next") instanceof String?(String)data.get("next"):null;readOnly=Boolean.TRUE.equals(data.get("readOnly"));loaded=true;changed();});}
 public void send(){if(sending||readOnly||adoptionId==null)return;if(pending()){attempt();return;}String text=body.trim();if(text.isEmpty()||text.codePointCount(0,text.length())>2000)return;pendingOperation=UUID.randomUUID().toString();pendingBody=text;state.set("flow_chat_owner",ticket.uid);state.set("flow_chat_operation",pendingOperation);state.set("flow_chat_body",pendingBody);attempt();}
 private void attempt(){if(sending||pendingOperation==null)return;sending=true;error="";long g=generation;Map<String,Object> input=new HashMap<>();input.put("adoptionId",adoptionId);input.put("operationId",pendingOperation);input.put("body",pendingBody);AdoptionApi.call("flowSend",input).addOnCompleteListener(t->{if(!current(g))return;sending=false;if(t.isSuccessful()){body="";clearPending();load(false);}else error="send";changed();});}
 private void clearPending(){pendingOperation=null;pendingBody=null;for(String k:new String[]{"flow_chat_owner","flow_chat_operation","flow_chat_body"})state.remove(k);}
 @Override protected void onCleared(){generation++;sessions.removeInvalidation(invalidation);messages.clear();body="";super.onCleared();}
}
